export const meta = { name: "__SLUG__", description: "__DESCRIPTION__" }

// Generated by the plan-workflow skill. Do not edit by hand: change the plan YAML and regenerate.
// The script only schedules. Agents do all file, git and shell work.

/**
 * @typedef {{path: string, action: string}} FileRef
 * @typedef {{given: string, when: string, then: string}} Criterion
 * @typedef {{id: string, title: string, depends_on: string[], files: FileRef[],
 *            acceptance_criteria: Criterion[], notes: string}} Step
 * @typedef {{title: string, slug: string, planPath: string, planBoardScript: string,
 *            hashCommand: string, planHash: string, steps: Step[]}} Plan
 * @typedef {{branch: string, pr: string, mode: 'stack'|'plain', parents: string[],
 *            unverified: boolean, wave: number, order: number, summary: string}} StepResult
 */

/** @type {Plan} */
const PLAN = __PLAN_JSON__

const MAX_PARALLEL = 3 // steps running at once
const STEP_RETRIES = 1 // extra tries for a failed step
const CI_FIX_ATTEMPTS = 3 // CI fix tries per PR, separate from step retries

// ---------------------------------------------------------------- input

/** `args` is a string like "base=develop dryRun" or an object {base, dryRun}. */
function parseArgs(a) {
  const out = { base: '', dryRun: false }
  if (typeof a === 'string') {
    for (const t of a.split(/\s+/).filter(Boolean)) {
      if (t === 'dryRun' || t === 'dryRun=true' || t === '--dry-run') out.dryRun = true
      else if (t.startsWith('base=')) out.base = t.slice(5)
    }
  } else if (a && typeof a === 'object') {
    out.base = a.base ? String(a.base) : ''
    out.dryRun = a.dryRun === true || a.dryRun === 'true'
  }
  return out
}

const OPTS = parseArgs(typeof args === 'undefined' ? undefined : args)
const BY_ID = Object.fromEntries(PLAN.steps.map((s) => [s.id, s]))

// ---------------------------------------------------------------- state

/** @type {Record<string, 'pending'|'done'|'failed'|'blocked'|'already_done'>} */
const state = {}
/** @type {Record<string, StepResult>} */
const results = {}
/** @type {Record<string, string>} why a step failed or is blocked */
const reasons = {}
/** @type {Record<string, {ci: string, note: string}>} */
const ciResults = {}
const stackClaimed = new Set() // parents that already have a stacked child
let finishCounter = 0 // the script cannot read the clock, so order finishes by count

async function safe(promise) {
  try {
    return await promise
  } catch (e) {
    log(`agent failed: ${e && e.message ? e.message : e}`)
    return null
  }
}

function chunk(list, n) {
  const out = []
  for (let i = 0; i < list.length; i += n) out.push(list.slice(i, i + n))
  return out
}

function isFinished(id) {
  return state[id] === 'done' || state[id] === 'already_done'
}

function readyIds() {
  return PLAN.steps
    .filter((s) => state[s.id] === 'pending' && s.depends_on.every(isFinished))
    .map((s) => s.id)
}

function markBlocked() {
  let changed = true
  while (changed) {
    changed = false
    for (const s of PLAN.steps) {
      if (state[s.id] !== 'pending') continue
      const bad = s.depends_on.find((d) => state[d] === 'failed' || state[d] === 'blocked')
      if (bad) {
        state[s.id] = 'blocked'
        reasons[s.id] = `waits on ${bad}, which did not finish`
        changed = true
      }
    }
  }
}

/** Plain list of waves for a dry run: what would run, in what order. */
function previewWaves() {
  const sim = {}
  for (const s of PLAN.steps) sim[s.id] = state[s.id] === 'already_done' ? 'done' : 'pending'
  const waves = []
  for (;;) {
    const ready = PLAN.steps.filter((s) => sim[s.id] === 'pending' && s.depends_on.every((d) => sim[d] === 'done'))
    if (!ready.length) break
    waves.push(ready.map((s) => s.id))
    for (const s of ready) sim[s.id] = 'done'
  }
  return waves
}

// ---------------------------------------------------------------- schemas

const PREFLIGHT_SCHEMA = {
  type: 'object',
  required: ['planHash', 'repoRoot', 'defaultBranch', 'statuses', 'ghStack', 'draftPrs', 'checks'],
  properties: {
    planHash: { type: 'string' },
    repoRoot: { type: 'string' },
    defaultBranch: { type: 'string' },
    statuses: { type: 'object', additionalProperties: { type: 'string' } },
    ghStack: { type: 'boolean' },
    ghStackNotes: { type: 'string' },
    draftPrs: { type: 'boolean' },
    checks: { type: 'array', items: { type: 'string' } },
    checksSource: { type: 'string' },
  },
}

const IMPLEMENT_SCHEMA = {
  type: 'object',
  required: ['ok', 'branch', 'worktree', 'summary'],
  properties: {
    ok: { type: 'boolean' },
    branch: { type: 'string' },
    worktree: { type: 'string' },
    summary: { type: 'string' },
  },
}

const CHECKS_SCHEMA = {
  type: 'object',
  required: ['passed', 'unverified', 'report'],
  properties: {
    passed: { type: 'boolean' },
    unverified: { type: 'boolean' },
    ran: { type: 'array', items: { type: 'string' } },
    report: { type: 'string' },
  },
}

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['allPass', 'verdicts'],
  properties: {
    allPass: { type: 'boolean' },
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        required: ['index', 'pass', 'reason'],
        properties: { index: { type: 'number' }, pass: { type: 'boolean' }, reason: { type: 'string' } },
      },
    },
  },
}

const PUBLISH_SCHEMA = {
  type: 'object',
  required: ['ok', 'pr', 'mode'],
  properties: {
    ok: { type: 'boolean' },
    pr: { type: 'string' },
    mode: { type: 'string', enum: ['stack', 'plain'] },
    note: { type: 'string' },
  },
}

const CI_SCHEMA = {
  type: 'object',
  required: ['state', 'summary'],
  properties: {
    state: { type: 'string', enum: ['green', 'red', 'none'] },
    summary: { type: 'string' },
  },
}

const FIX_SCHEMA = {
  type: 'object',
  required: ['ok', 'sha'],
  properties: { ok: { type: 'boolean' }, sha: { type: 'string' }, note: { type: 'string' } },
}

const OK_SCHEMA = {
  type: 'object',
  required: ['ok'],
  properties: { ok: { type: 'boolean' }, note: { type: 'string' } },
}

// ---------------------------------------------------------------- prompts

function stepBrief(step) {
  const files = step.files.map((f) => `- ${f.action} ${f.path}`).join('\n') || '- (none listed)'
  const ac =
    step.acceptance_criteria
      .map((c, i) => `${i + 1}. Given ${c.given}; When ${c.when}; Then ${c.then}`)
      .join('\n') || '(none written: use the title and notes)'
  return [
    `Step "${step.id}": ${step.title}`,
    `Files:\n${files}`,
    `Acceptance criteria:\n${ac}`,
    step.notes ? `Notes:\n${step.notes}` : '',
  ]
    .filter(Boolean)
    .join('\n\n')
}

function preflightPrompt() {
  return `You are the preflight check for a plan workflow. Do not change anything: read only.
1. Run this command and report its output as planHash: ${PLAN.hashCommand}
2. Report repoRoot (git rev-parse --show-toplevel) and defaultBranch (the remote's default branch, e.g. from \`git symbolic-ref refs/remotes/origin/HEAD\` or \`gh repo view\`).
3. Read the plan file ${PLAN.planPath} and report each step's \`status\` in statuses ({id: status}). A step with no status is "not_started".
4. Report ghStack: true only if the \`gh stack\` extension is installed and usable (check \`gh stack --help\`). Put anything odd in ghStackNotes. Do not install anything.
5. Report draftPrs: true if you can open draft pull requests in this repo (check that \`gh auth status\` works and the remote is on GitHub). Do not open one.
6. Report checks: the shell commands this repo itself uses to check changes (lint, format, typecheck, unit tests). Look in CLAUDE.md, AGENTS.md, README, Makefile, package.json scripts, CI config. Prefer the fast ones. Empty list if there are none. Put where you found them in checksSource.`
}

/** Where a step's branch starts, which branches get merged in, and how it is published. */
function planGit(step, ctx) {
  // Steps that were already done before this run have no branch here: assume they are merged into the base.
  const parents = step.depends_on.filter((d) => results[d])
  const base = OPTS.base || ctx.defaultBranch
  if (parents.length === 0) {
    return { startRef: `origin/${base}`, merge: [], mode: ctx.ghStack ? 'stack' : 'plain', parents, base }
  }
  const byFinish = [...parents].sort((a, b) => results[a].order - results[b].order)
  const last = byFinish[byFinish.length - 1]
  const merge = byFinish.slice(0, -1)
  const canStack = ctx.ghStack && parents.length === 1 && results[last].mode === 'stack' && !stackClaimed.has(last)
  if (canStack) stackClaimed.add(last)
  return {
    startRef: results[last].branch,
    merge: merge.map((p) => results[p].branch),
    mode: canStack ? 'stack' : 'plain',
    parents,
    base: results[last].branch,
  }
}

function implementPrompt(step, g, ctx, feedback, previous) {
  const wt = `${ctx.repoRoot}/../.plan-workflow-${PLAN.slug}/${step.id}`
  const branch = `plan/${PLAN.slug}/${step.id}`
  const start = previous
    ? `Continue in the existing worktree ${previous.worktree} (branch ${previous.branch}). Do not create a new one.`
    : [
        `Work in your own git worktree, never in the main checkout:`,
        `  git fetch origin && git worktree add -b ${branch} ${wt} ${g.startRef}`,
        `If that fails because the branch or worktree already exists from an earlier try, reuse it as it is instead of failing.`,
        g.merge.length
          ? `Then merge these finished parent branches into it, resolving conflicts: ${g.merge.join(', ')}.`
          : '',
      ]
        .filter(Boolean)
        .join('\n')
  return `You are building one step of the plan "${PLAN.title}".

${stepBrief(step)}

${start}

Rules:
- Write the tests and the implementation together, in this one pass. Treat the acceptance criteria as the tests to satisfy.
- Touch only what the step needs. Follow the repo's own conventions (CLAUDE.md, AGENTS.md).
- Keep exactly one commit for this step on top of the start point. Do not push. Do not edit the plan YAML.
- If the step cannot be done as written, set ok to false and say why in summary.
${feedback ? `\nA previous attempt failed. Fix this first:\n${feedback}\n` : ''}
Report branch, worktree (absolute path) and a short summary.`
}

function checksPrompt(step, impl, ctx) {
  const list = ctx.checks.length
    ? `Run these checks (found in ${ctx.checksSource || 'the repo'}):\n${ctx.checks.map((c) => `- ${c}`).join('\n')}`
    : 'The preflight found no checks. Look once more in CLAUDE.md, AGENTS.md, the Makefile and package scripts. If there are really none, set unverified to true and passed to true.'
  return `Work in the worktree ${impl.worktree} (branch ${impl.branch}), step "${step.id}": ${step.title}.
${list}
Fix every failure you find, keep the step to ONE commit (amend it), and run the checks again until they pass or you are sure you cannot fix them. Do not push.
Report passed, unverified, the commands you ran in ran, and a short report of the final results (and what is still failing, if anything).`
}

function judgePrompt(step, impl, checks) {
  return `You are an independent reviewer. You did not write this code. Judge each acceptance criterion of step "${step.id}" (${step.title}) from the actual change and the check results. Do not edit anything.

Change: run \`git -C ${impl.worktree} show HEAD\` and read the files it touches.
Check results:
${checks.report}

Criteria:
${step.acceptance_criteria.map((c, i) => `${i + 1}. Given ${c.given}; When ${c.when}; Then ${c.then}`).join('\n') || '(none written: judge whether the change does what the title and notes say, as one criterion numbered 1)'}

For each criterion give index (starting at 1), pass, and a one-line reason. Pass only when the change and the checks show it. Set allPass true only if every criterion passes.`
}

function publishPrompt(step, impl, g, checks, ctx) {
  const how =
    g.mode === 'stack'
      ? `This branch continues a GitHub stack. ${g.parents.length ? `It goes on top of the stack branch ${g.base}.` : `It starts a new stack on ${g.base}.`} Run \`gh stack --help\` and the help of the subcommands you use first; do not guess flags. Push and submit the branch as a draft PR in the stack. If the stack tooling fails, fall back to a plain draft PR and report mode "plain".`
      : `Open a plain pull request with base branch ${g.base}.${g.merge.length ? ` This step merged in several parents; name all of them in the description: ${g.parents.join(', ')}.` : ''}`
  const draft = ctx.draftPrs
    ? 'Open it as a DRAFT.'
    : 'Draft PRs are not available here; open a normal PR and say so in the description.'
  return `Publish step "${step.id}": ${step.title}.
Worktree ${impl.worktree}, branch ${impl.branch}.
Push the branch and open the pull request. ${how} ${draft}
PR title: "${PLAN.title}: ${step.title}". Description: what the step does, its acceptance criteria, and ${checks.unverified ? 'a clear line: "Unverified: no repo checks were found to run."' : `the checks that passed (${(checks.ran || []).join(', ') || 'see report'})`}.
Do not edit the plan YAML. Report the PR URL in pr, the mode you really used, and anything notable in note.`
}

function ciWatchPrompt(step, r, sha) {
  const only = sha ? `Only count check runs for commit ${sha} (the latest push). Ignore older runs; if none has started for it yet, wait for it. ` : ''
  return `${only}Watch CI on the pull request ${r.pr} (branch ${r.branch}) with \`gh pr checks --watch\` or similar. Wait until the checks finish. Report state "green" if all pass, "red" if any fail (summary: which checks and the key error lines), or "none" if the repo has no CI for this PR.`
}

function ciFixPrompt(step, r, summary, descendants, attempt) {
  return `CI is red on ${r.pr} (step "${step.id}", fix attempt ${attempt} of ${CI_FIX_ATTEMPTS}).
Failure:
${summary}

Work in its worktree (or make one with \`git worktree add\` on branch ${r.branch}). Find the root cause and fix it with a small change. Never skip or disable a test. Run the repo's own checks, then commit and push to the same branch.
${descendants.length ? `Then bring the fix into the branches built on top of it and push them: ${descendants.join(', ')} (merge ${r.branch} into each; if they are part of a gh stack, restack with that tool instead of merging).` : ''}
Report ok true if you pushed a fix, and sha: the full SHA of the commit you pushed on ${r.branch}.`
}

function ciCommentPrompt(step, r, summary) {
  return `CI is still red on ${r.pr} after ${CI_FIX_ATTEMPTS} fix attempts. Leave the PR as it is (still a draft if it is one) and add one PR comment saying exactly what is red and what was tried. Failure summary:\n${summary}\nEnd the comment with a blank line, a --- line, then: _Generated by Claude Code_`
}

/** Quote a value for a POSIX shell. */
function q(v) {
  return `'${String(v).replace(/'/g, `'\\''`)}'`
}

function statusPrompt(updates) {
  const cmds = updates
    .map((u) => `python3 ${q(PLAN.planBoardScript)} status ${q(PLAN.planPath)} ${q(u.id)} ${u.status}`)
    .join('\n')
  return `Run these in the main checkout (not a worktree), one by one. Use the commands exactly; do not edit the YAML by hand and do not commit it.\n${cmds}\nIf one is refused, report ok false and say which in note.`
}

// ---------------------------------------------------------------- one step

async function runStep(stepId, ctx, wave) {
  const step = BY_ID[stepId]
  const g = planGit(step, ctx)
  let feedback = ''
  let impl = null
  let lastReason = 'unknown'
  for (let attempt = 0; attempt <= STEP_RETRIES; attempt++) {
    const label = attempt ? `${step.id} (retry)` : step.id
    const made = await safe(agent(implementPrompt(step, g, ctx, feedback, impl), { schema: IMPLEMENT_SCHEMA, label: `${label}: build` }))
    if (!made || !made.ok) {
      lastReason = made ? `could not build: ${made.summary}` : 'build agent failed'
      feedback = lastReason
      if (made && made.worktree) impl = made
      continue
    }
    impl = made
    const checks = await safe(agent(checksPrompt(step, impl, ctx), { schema: CHECKS_SCHEMA, label: `${label}: checks` }))
    if (!checks || !checks.passed) {
      lastReason = checks ? `checks failed: ${checks.report}` : 'checks agent failed'
      feedback = lastReason
      continue
    }
    const judged = await safe(agent(judgePrompt(step, impl, checks), { schema: JUDGE_SCHEMA, label: `${label}: review` }))
    if (!judged) {
      lastReason = 'review agent failed'
      feedback = 'The reviewer did not return a verdict. Re-check each acceptance criterion.'
      continue
    }
    // Do not trust allPass alone: every criterion needs its own passing verdict.
    const needed = Math.max(1, step.acceptance_criteria.length)
    const missing = []
    for (let i = 1; i <= needed; i++) {
      if (!judged.verdicts.some((v) => v.index === i && v.pass)) missing.push(i)
    }
    if (!judged.allPass || missing.length) {
      const bad = judged.verdicts.filter((v) => !v.pass).map((v) => `criterion ${v.index}: ${v.reason}`)
      if (!bad.length) bad.push(`no passing verdict for criterion ${missing.join(', ')}`)
      lastReason = `review failed: ${bad.join('; ') || 'a criterion did not pass'}`
      feedback = lastReason
      continue
    }
    let pub = null
    for (let t = 0; t < 2 && !(pub && pub.ok); t++) {
      pub = await safe(agent(publishPrompt(step, impl, g, checks, ctx), { schema: PUBLISH_SCHEMA, label: `${label}: publish` }))
    }
    if (!pub || !pub.ok) {
      lastReason = `could not publish${pub && pub.note ? `: ${pub.note}` : ''}`
      feedback = lastReason
      continue
    }
    results[step.id] = {
      branch: impl.branch,
      pr: pub.pr,
      mode: pub.mode,
      parents: step.depends_on,
      unverified: !!checks.unverified,
      wave,
      order: ++finishCounter,
      summary: impl.summary,
    }
    return true
  }
  reasons[step.id] = lastReason
  return false
}

// ---------------------------------------------------------------- run

function descendantsOf(id) {
  const out = []
  for (const s of PLAN.steps) {
    if (s.depends_on.includes(id)) {
      if (results[s.id]) out.push(results[s.id].branch)
      out.push(...descendantsOf(s.id))
    }
  }
  return [...new Set(out)]
}

async function watchCi(stepId) {
  const step = BY_ID[stepId]
  const r = results[stepId]
  let fixes = 0
  let sha = ''
  for (;;) {
    const w = await safe(agent(ciWatchPrompt(step, r, sha), { schema: CI_SCHEMA, label: `${step.id}: CI` }))
    if (!w) return { ci: 'unknown', note: 'CI watcher failed' }
    if (w.state === 'green') return { ci: 'green', note: '' }
    if (w.state === 'none') return { ci: 'none', note: 'no CI on this PR' }
    if (fixes >= CI_FIX_ATTEMPTS) {
      await safe(agent(ciCommentPrompt(step, r, w.summary), { schema: OK_SCHEMA, label: `${step.id}: CI comment` }))
      return { ci: 'red', note: w.summary }
    }
    fixes++
    const fix = await safe(agent(ciFixPrompt(step, r, w.summary, descendantsOf(stepId), fixes), { schema: FIX_SCHEMA, label: `${step.id}: CI fix ${fixes}` }))
    if (fix && fix.ok && fix.sha) sha = fix.sha
  }
}

const statusProblems = []
async function writeStatus(updates, label) {
  const r = await safe(agent(statusPrompt(updates), { schema: OK_SCHEMA, label }))
  if (!r || !r.ok) statusProblems.push(`${label}: ${r && r.note ? r.note : 'status write failed'}`)
}

function buildReport(ctx) {
  const rows = PLAN.steps.map((s) => {
    const r = results[s.id]
    const ci = ciResults[s.id]
    return {
      id: s.id,
      title: s.title,
      outcome: state[s.id],
      pr: r ? r.pr : '',
      mode: r ? r.mode : '',
      unverified: r ? r.unverified : false,
      ci: ci ? ci.ci : '',
      reason: reasons[s.id] || (ci && ci.ci === 'red' ? `CI red: ${ci.note}` : ''),
    }
  })
  const by = (o) => rows.filter((r) => r.outcome === o)
  const text = [
    `Plan "${PLAN.title}"`,
    `Done: ${by('done').map((r) => r.id).join(', ') || 'none'}`,
    `Already done before the run: ${by('already_done').map((r) => r.id).join(', ') || 'none'}`,
    `Failed: ${by('failed').map((r) => `${r.id} (${r.reason})`).join('; ') || 'none'}`,
    `Blocked: ${by('blocked').map((r) => `${r.id} (${r.reason})`).join('; ') || 'none'}`,
    `Unverified (no checks found): ${rows.filter((r) => r.unverified).map((r) => r.id).join(', ') || 'none'}`,
    `CI still red: ${rows.filter((r) => r.ci === 'red').map((r) => r.id).join(', ') || 'none'}`,
    `Status file problems: ${statusProblems.join('; ') || 'none'}`,
    `Real stacks used: ${rows.some((r) => r.mode === 'stack') ? 'yes' : 'no'}`,
    ...rows.filter((r) => r.pr).map((r) => `PR ${r.id}: ${r.pr}`),
  ].join('\n')
  return { steps: rows, text, stacksUsed: rows.some((r) => r.mode === 'stack') }
}

phase('Preflight')
const pre = await agent(preflightPrompt(), { schema: PREFLIGHT_SCHEMA, label: 'preflight' })
if (!pre) throw new Error('preflight agent failed')
if (pre.planHash !== PLAN.planHash) {
  throw new Error(`plan changed, regenerate (workflow has ${PLAN.planHash}, the file now gives ${pre.planHash})`)
}
for (const s of PLAN.steps) state[s.id] = pre.statuses[s.id] === 'done' ? 'already_done' : 'pending'
const ctx = {
  repoRoot: pre.repoRoot,
  defaultBranch: pre.defaultBranch,
  ghStack: pre.ghStack,
  draftPrs: pre.draftPrs,
  checks: pre.checks,
  checksSource: pre.checksSource || '',
}

if (OPTS.dryRun) {
  const waves = previewWaves()
  const lines = waves.map(
    (w, i) =>
      `Wave ${i + 1}: ` +
      w.map((id) => `${id} [${BY_ID[id].files.map((f) => `${f.action} ${f.path}`).join(', ') || 'no files listed'}]`).join('; '),
  )
  const text = [`Dry run for "${PLAN.title}". Base: ${OPTS.base || ctx.defaultBranch}.`, ...lines].join('\n')
  log(text)
  return { dryRun: true, waves, text }
}

let waveNo = 0
for (;;) {
  markBlocked()
  const ready = readyIds()
  if (!ready.length) break
  waveNo++
  phase(`Wave ${waveNo}`)
  await writeStatus(ready.map((id) => ({ id, status: 'in_progress' })), `wave ${waveNo}: status start`)
  for (const group of chunk(ready, MAX_PARALLEL)) {
    const done = await pipeline(group, (id) => runStep(id, ctx, waveNo))
    group.forEach((id, i) => {
      state[id] = done[i] === true ? 'done' : 'failed'
      if (state[id] === 'failed' && !reasons[id]) reasons[id] = 'step agent failed'
    })
  }
  await writeStatus(ready.map((id) => ({ id, status: state[id] === 'done' ? 'done' : 'not_started' })), `wave ${waveNo}: status end`)
}

const stuck = PLAN.steps.filter((s) => state[s.id] === 'pending')
if (stuck.length) throw new Error(`dependency cycle or unreachable steps: ${stuck.map((s) => s.id).join(', ')}`)

phase('CI')
const withPr = PLAN.steps.filter((s) => state[s.id] === 'done')
const layers = [...new Set(withPr.map((s) => results[s.id].wave))].sort((a, b) => a - b)
for (const w of layers) {
  const ids = withPr.filter((s) => results[s.id].wave === w).map((s) => s.id)
  for (const group of chunk(ids, MAX_PARALLEL)) {
    const out = await pipeline(group, (id) => watchCi(id))
    group.forEach((id, i) => {
      ciResults[id] = out[i] || { ci: 'unknown', note: 'CI agent failed' }
    })
  }
}

const report = buildReport(ctx)
log(report.text)
return report
